type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.GetHealth, options.OperationMiddlewares["getHealth"]...)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login, options.OperationMiddlewares["login"]...)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout, options.OperationMiddlewares["logout"]...)
	router.GET(options.BaseURL+"/auth/oidc/providers", wrapper.ListLoginProviders, options.OperationMiddlewares["listLoginProviders"]...)
	router.GET(options.BaseURL+"/auth/oidc/:code/login", wrapper.StartOidcLogin, options.OperationMiddlewares["startOidcLogin"]...)
	router.GET(options.BaseURL+"/auth/oidc/:code/link", wrapper.StartOidcLink, options.OperationMiddlewares["startOidcLink"]...)
	router.GET(options.BaseURL+"/auth/oidc/callback", wrapper.OidcCallback, options.OperationMiddlewares["oidcCallback"]...)
	router.GET(options.BaseURL+"/oidc-providers", wrapper.ListOidcProviders, options.OperationMiddlewares["listOidcProviders"]...)
	router.POST(options.BaseURL+"/oidc-providers", wrapper.CreateOidcProvider, options.OperationMiddlewares["createOidcProvider"]...)
	router.DELETE(options.BaseURL+"/oidc-providers/:id", wrapper.DeleteOidcProvider, options.OperationMiddlewares["deleteOidcProvider"]...)
	router.PUT(options.BaseURL+"/oidc-providers/:id", wrapper.UpdateOidcProvider, options.OperationMiddlewares["updateOidcProvider"]...)
	router.GET(options.BaseURL+"/me", wrapper.GetCurrentUser, options.OperationMiddlewares["getCurrentUser"]...)
	router.PUT(options.BaseURL+"/me/password", wrapper.ChangePassword, options.OperationMiddlewares["changePassword"]...)
	router.GET(options.BaseURL+"/me/identities", wrapper.ListMyIdentities, options.OperationMiddlewares["listMyIdentities"]...)
	router.DELETE(options.BaseURL+"/me/identities/:id", wrapper.UnlinkMyIdentity, options.OperationMiddlewares["unlinkMyIdentity"]...)
	router.GET(options.BaseURL+"/me/preferences", wrapper.GetPreferences, options.OperationMiddlewares["getPreferences"]...)
	router.PUT(options.BaseURL+"/me/preferences", wrapper.UpdatePreferences, options.OperationMiddlewares["updatePreferences"]...)
	router.GET(options.BaseURL+"/budgets", wrapper.ListBudgets, options.OperationMiddlewares["listBudgets"]...)
	router.POST(options.BaseURL+"/budgets", wrapper.CreateBudget, options.OperationMiddlewares["createBudget"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId", wrapper.GetBudget, options.OperationMiddlewares["getBudget"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId", wrapper.UpdateBudget, options.OperationMiddlewares["updateBudget"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/summary", wrapper.GetBudgetSummary, options.OperationMiddlewares["getBudgetSummary"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/accounts", wrapper.ListAccounts, options.OperationMiddlewares["listAccounts"]...)
	router.POST(options.BaseURL+"/budgets/:budgetId/accounts", wrapper.CreateAccount, options.OperationMiddlewares["createAccount"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId/accounts/order", wrapper.ReorderAccounts, options.OperationMiddlewares["reorderAccounts"]...)
	router.DELETE(options.BaseURL+"/budgets/:budgetId/accounts/:accountId", wrapper.DeleteAccount, options.OperationMiddlewares["deleteAccount"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId/accounts/:accountId", wrapper.UpdateAccount, options.OperationMiddlewares["updateAccount"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/categories", wrapper.ListCategories, options.OperationMiddlewares["listCategories"]...)
	router.POST(options.BaseURL+"/budgets/:budgetId/categories", wrapper.CreateCategory, options.OperationMiddlewares["createCategory"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId/categories/order", wrapper.ReorderCategories, options.OperationMiddlewares["reorderCategories"]...)
	router.DELETE(options.BaseURL+"/budgets/:budgetId/categories/:categoryId", wrapper.DeleteCategory, options.OperationMiddlewares["deleteCategory"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId/categories/:categoryId", wrapper.UpdateCategory, options.OperationMiddlewares["updateCategory"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/accounts/:accountId/register", wrapper.GetRegister, options.OperationMiddlewares["getRegister"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/register", wrapper.GetScopeRegister, options.OperationMiddlewares["getScopeRegister"]...)
	router.GET(options.BaseURL+"/budgets/:budgetId/payees", wrapper.ListPayees, options.OperationMiddlewares["listPayees"]...)
	router.DELETE(options.BaseURL+"/budgets/:budgetId/payees/:payeeId", wrapper.DeletePayee, options.OperationMiddlewares["deletePayee"]...)
	router.PUT(options.BaseURL+"/budgets/:budgetId/payees/:payeeId", wrapper.RenamePayee, options.OperationMiddlewares["renamePayee"]...)
	router.POST(options.BaseURL+"/budgets/:budgetId/payees/:payeeId/merge", wrapper.MergePayees, options.OperationMiddlewares["mergePayees"]...)
	router.POST(options.BaseURL+"/budgets/:budgetId/transactions/batch", wrapper.SaveTransactions, options.OperationMiddlewares["saveTransactions"]...)

}

